type TimePickerContentProps = Omit<
  React.ComponentProps<typeof Popover>,
  "children" | "isOpen" | "onOpenChange" | "triggerRef"
> & {
  /** Replaces the columns and the footer. */
  children?: React.ReactNode;
};

/**
 * The popover: columns and footer by default. A modal react-aria `Popover`
 * around a `Dialog`, so Tab cycles inside it, Escape and an outside press
 * close it, and focus returns to the trigger. The first column takes focus on
 * open.
 */
function TimePickerContent({
  className,
  placement = "bottom start",
  children,
  ...props
}: TimePickerContentProps) {
  const context = useTimePickerContext("TimePickerContent");
  return (
    <Popover
      placement={placement}
      triggerRef={context.triggerRef}
      isOpen={context.isOpen}
      onOpenChange={context.setOpen}
      className={cn("w-auto gap-0 overflow-hidden p-0", className)}
      {...props}
    >
      <Dialog
        aria-labelledby={context.labelledBy}
        aria-label={
          context.labelledBy ? undefined : (context.label ?? context.i18n.labels.panelLabel)
        }
        className="outline-none"
      >
        <SurfaceContext.Provider value="popup">
          <FocusFirstColumn />
          {children === undefined ? (
            <>
              <TimePickerColumns />
              <TimePickerFooter />
            </>
          ) : (
            children
          )}
        </SurfaceContext.Provider>
      </Dialog>
    </Popover>
  );
}

/* Once per open. Child effects run before the Dialog's own, which then sees
   focus inside and leaves it on the column. */
function FocusFirstColumn() {
  const context = useTimePickerContext("TimePickerContent");
  const getColumns = React.useRef(context.getColumns);
  React.useEffect(() => {
    getColumns.current()?.querySelector<HTMLElement>(LIST_SELECTOR)?.focus({ preventScroll: true });
  }, []);
  return null;
}

type TimePickerPanelProps = React.ComponentProps<"div">;

/**
 * The columns and the footer, rendered in place: put it straight inside a
 * `TimePicker`, with no trigger or content, for an always-open picker.
