type TimePickerFooterProps = React.ComponentProps<"div">;

/** The action row. Without children: Now and Clear, plus OK in a popover or under `requireConfirm`. */
function TimePickerFooter({ className, children, ...props }: TimePickerFooterProps) {
  const context = useTimePickerContext("TimePickerFooter");
  const popup = React.useContext(SurfaceContext) === "popup";
  return (
    <div
      data-slot="time-picker-footer"
      className={cn("flex items-center justify-between gap-2 border-t p-1.5", className)}
      {...props}
    >
      {children === undefined ? (
        <>
          <TimePickerNow />
          <TimePickerClear />
          {(popup || context.requireConfirm) && <TimePickerConfirm />}
        </>
      ) : (
        children
      )}
    </div>
  );
}

type TimePickerActionProps = Omit<React.ComponentProps<typeof Button>, "children"> & {
  children?: React.ReactNode;
};

/** Sets the current time, floored to the steps and moved inside the bounds. */
function TimePickerNow({
  variant = "ghost",
  size = "sm",
  onPress,
  children,
  ...props
}: TimePickerActionProps) {
  const context = useTimePickerContext("TimePickerNow");
  return (
    <Button
      variant={variant}
      size={size}
      isDisabled={context.isDisabled || context.isReadOnly}
      data-slot="time-picker-now"
      onPress={(event) => {
        onPress?.(event);
        pickNow(context);
      }}
      {...props}
    >
      {children === undefined ? context.i18n.labels.now : children}
    </Button>
  );
}

/** Empties the value, then hands focus to the first column. */
function TimePickerClear({
  variant = "ghost",
  size = "sm",
  className,
  onPress,
  children,
  ...props
}: TimePickerActionProps) {
  const context = useTimePickerContext("TimePickerClear");
  return (
    <Button
      variant={variant}
      size={size}
      isDisabled={context.isDisabled || context.isReadOnly}
      data-slot="time-picker-clear"
      className={cn("text-muted-foreground", className)}
      onPress={(event) => {
        onPress?.(event);
        context.select(null);
        context
          .getColumns()
          ?.querySelector<HTMLElement>(LIST_SELECTOR)
          ?.focus({ preventScroll: true });
      }}
      {...props}
    >
      {children === undefined ? context.i18n.labels.clear : children}
    </Button>
  );
}

/** Commits a pending draft and closes the popover. */
function TimePickerConfirm({
  variant,
  size = "sm",
  onPress,
  children,
  ...props
}: TimePickerActionProps) {
  const context = useTimePickerContext("TimePickerConfirm");
  return (
    <Button
      variant={variant ?? (context.requireConfirm ? "default" : "secondary")}
      size={size}
      isDisabled={context.isDisabled}
      data-slot="time-picker-confirm"
      onPress={(event) => {
        onPress?.(event);
        context.confirm();
      }}
      {...props}
    >
      {children === undefined ? context.i18n.labels.confirm : children}
    </Button>
  );
}

